/*
 * A259275  G.f.: A(x) = exp( Sum_{n>=1} 5^n * x^n/(n*(1+x^n)) ).
 * https://oeis.org/A259275
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = exp( Sum_{m>=1} 5^m x^m/(m*(1+x^m)) ) Generated by the
 *            recurrence: a(0) = 1 for n>=1: a(n) = (1/n) * sum_{k=1..n}
 *            a(n-k) * E(k) where E(k) = sum_{d|k} (-1)^{k/d-1} * 5^d
 * Range:     u8 n <= 2, u16 n <= 5, u32 n <= 12, u64 n <= 24, u128 n <= 24,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static seq_t *A        = NULL; /* a(n) values          */
static seq_t *E        = NULL; /* E(k) values          */
static seq_t *pow5     = NULL; /* 5^i values           */
static size_t A_size   = 0;    /* current allocated size (>= needed) */

/* enlarge internal arrays to hold indices up to n */
static void ensure_arrays(idx_t n)
{
    size_t need = (size_t)n + 1;
    if (need <= A_size)
        return;                     /* already big enough */

    /* reallocate memory for the new size */
    pow5 = (seq_t*)realloc(pow5, need * sizeof(seq_t));
    E   = (seq_t*)realloc(E,   need * sizeof(seq_t));
    A   = (seq_t*)realloc(A,   need * sizeof(seq_t));

    /* initialise the newly added entries */
    for (size_t i = A_size; i < need; ++i)
    {
        if (i == 0)                /* base case */
        {
            pow5[0] = (seq_t)1;
            E[0]    = (seq_t)0;
            A[0]    = (seq_t)1;
        }
        else
        {
            /* 5^i */
            pow5[i] = pow5[i - 1] * (seq_t)5;

            /* compute E(i) = sum_{d|i} (-1)^{i/d-1} * 5^d */
            seq_t pos = 0, neg = 0;
            for (size_t d = 1; d * d <= i; ++d)
            {
                if (i % d == 0)
                {
                    size_t d1 = d, d2 = i / d;

                    /* divisor d1 */
                    seq_t term1 = pow5[d1] * (seq_t)d2;
                    if ((d2 & 1) == 1) pos += term1; else neg += term1;

                    /* divisor d2 (if distinct) */
                    if (d1 != d2)
                    {
                        seq_t term2 = pow5[d2] * (seq_t)d1;
                        if ((d1 & 1) == 1) pos += term2; else neg += term2;
                    }
                }
            }
            E[i] = pos - neg;   /* pos > neg for all i in this sequence */

            /* compute a[i] using the recurrence */
            seq_t sum = 0;
            for (size_t k = 1; k <= i; ++k)
                sum += A[i - k] * E[k];
            A[i] = sum / (seq_t)i;
        }
    }
    A_size = need;
}

/* public API: returns a(n) */
seq_t a(idx_t n)
{
    ensure_arrays(n);
    return A[(size_t)n];
}
